from test_profile_clarity import tests
from test_bufftap import test
from test_blessings import setup

solo=setup+"BuffTap.db.group=false; BuffTap.db.blessingAssignments=false; BuffTap.db.buffs.bok=false; BuffTap.db.buffs.bom=false; BuffTap.db.buffs.bow=false; BuffTap.db.buffs.bol=false; BuffTap.db.buffs.bos=true; BuffTap:InvalidateRoster(); refresh(); "
party=setup+"BuffTap.db.salvationGroup=true; classes.party2='WARRIOR'; BuffTap.db.blessingClasses={PALADIN='skip',WARRIOR='skip'}; BuffTap.db.buffs.bos=true; BuffTap.db.priorities.bos=1; BuffTap:SetBlessingPlayer({unit='player'},nil,true); BuffTap:InvalidateRoster(); refresh(); "

test('Salvation uses verified current spell identity',solo+"assert(BuffTap.action.id==1038 and BuffTap.action.name=='Salvation'); assert(BuffTap:FindBuff('bos').kind=='single' and BuffTap:FindBuff('gbos').name=='Mass Salvation')")
test('Salvation and own Kings coexist in personal queue',solo+"aura('player',20217,'Blessing of Kings'); auras.player[1].sourceUnit='player'; refresh(); assert(BuffTap.action.key=='bos')")
test('Own Salvation does not occupy a blessing slot',solo+"BuffTap.db.buffs.bok=true; BuffTap.db.priorities.bok=1; aura('player',1038,'Salvation'); auras.player[1].sourceUnit='player'; refresh(); assert(BuffTap.action.key=='bok')")
test('Mass Salvation covers single Salvation by spell ID',solo+"aura('player',25895,'Mass Salvation'); refresh(); assert(not BuffTap.action)")
test('Unknown Salvation caster does not block ordinary blessing priorities',setup+"aura('party1',1038,'Salvation'); BuffTap.db.blessingClasses.WARRIOR='priority'; BuffTap.db.groupBlessingPriorities.WARRIOR={'bom','bow'}; refresh(); assert(BuffTap.action.key=='bom')")
test('Mass Salvation groups same class across raid subgroups',party+"IsInRaid=function() return true end; GetNumGroupMembers=function() return 3 end; UnitIsUnit=function(a,b) return a==b or a=='raid1' and b=='player' end; UnitGUID=function(u) return 'Player-'..(u=='raid1' and 'player' or u) end; UnitExists=function(u) return u=='player' or u=='raid1' or u=='raid2' or u=='raid3' end; UnitClass=function(u) return 'Class',u=='player' or u=='raid1' and 'PALADIN' or 'WARRIOR' end; UnitClass=function(u) return 'Class',(u=='player' or u=='raid1') and 'PALADIN' or 'WARRIOR' end; GetRaidRosterInfo=function(i) return 'Name'..i,0,i end; BuffTap:InvalidateRoster(); refresh(); assert(BuffTap.action.id==25895 and BuffTap.action.groupCount==2)")
test('Mass Salvation requires Symbol of Kings',party+"bags[21177]=0; refresh(); assert(BuffTap.action.id==1038 and not BuffTap.action.groupCast)")
test('Mass Salvation normal threshold uses class-wide threshold',party+"BuffTap.db.blessingNeed=3; refresh(); assert(BuffTap.action.id==1038)")
test('Never Salvation blocks class-wide application and allows safe single',party+"BuffTap:SetBlessingPlayer({unit='party2'},nil,true); refresh(); assert(BuffTap.action.id==1038 and BuffTap.action.target=='party1')")
test('Never Salvation remains active without blessing assignments',party+"BuffTap.db.blessingAssignments=false; BuffTap.db.buffs.bok=false; BuffTap.db.buffs.bom=false; BuffTap.db.buffs.bow=false; BuffTap:SetBlessingPlayer({unit='party2'},nil,true); refresh(); assert(BuffTap.action.id==1038 and BuffTap.action.target=='party1')")
test('Changed Never Salvation invalidates prepared Mass before click',party+"assert(BuffTap.action.id==25895); BuffTap:SetBlessingPlayer({unit='party2'},nil,true); BuffTap.button.scripts.PreClick(nil,'LeftButton',true); assert(not BuffTap.action and not BuffTap.button.attrs.type1)")
test('Class-wide Salvation checks excluded subgroup before click',party+"assert(BuffTap.action.id==25895); BuffTap.db.buffGroups.bos={[1]=false}; BuffTap.button.scripts.PreClick(nil,'LeftButton',true); assert(not BuffTap.action)")
test('Incomplete roster cannot qualify for Mass Salvation',party+"GetNumSubgroupMembers=function() return 3 end; UnitExists=function(u) return u~='party3' end; BuffTap:InvalidateRoster(); refresh(); assert(BuffTap.action.id==1038 and not BuffTap.action.groupCast)")
test('Unknown affected class prevents Mass Salvation',party+"classes.party2=nil; BuffTap:InvalidateRoster(); refresh(); assert(not BuffTap:SalvationMassSafe('WARRIOR',BuffTap:Roster()) and BuffTap.action.id~=25895)")
test('Salvation is never offered to a passerby',solo+"BuffTap.db.friendlyTarget=true; BuffTap.db.targetBuffs.bos=true; refresh(); assert(not BuffTap.action.quickTarget)")
test('Friendly group target works with general group buffing off',solo+"BuffTap.db.friendlyTarget=true; BuffTap.db.targetBuffs.bos=true; UnitGUID=function(u) return 'Player-'..(u=='target' and 'party1' or u) end; refresh(); assert(BuffTap.action.quickTarget and BuffTap.action.id==1038)")
test('Legacy Salvation migration pauses opt-ins but retains exclusions and other blessings',setup+"BuffTap.db.salvationVersion=nil; BuffTap.db.buffs.bos=true; BuffTap.db.blessingClasses.WARRIOR='bos'; BuffTap.db.targetBlessingClasses.PRIEST='bos'; BuffTap.db.groupBlessingPriorities.WARRIOR={'bos','bok','bow','bol','bom'}; BuffTap.db.buffClasses.bos={WARRIOR=false}; BuffTap:InitDB(); assert(not BuffTap.db.buffs.bos and BuffTap.db.blessingClasses.WARRIOR=='skip' and BuffTap.db.targetBlessingClasses.PRIEST=='skip'); assert(#BuffTap.db.groupBlessingPriorities.WARRIOR==4 and BuffTap.db.groupBlessingPriorities.WARRIOR[4]=='bom'); assert(BuffTap.db.salvationMigration.classes.WARRIOR=='bos' and BuffTap.db.buffClasses.bos.WARRIOR==false)")
test('Salvation migration does not repeat after explicit re-enable',solo+"BuffTap:InitDB(); assert(BuffTap.db.buffs.bos)")
test('Blessing editor excludes independent Salvation',setup+"for _,key in ipairs(BuffTap.BlessingFamilies) do assert(key~='bos') end; BuffTap:Options(); local p=BuffTap.options.blessingRows[1].pick; p.scripts.OnClick(p); for _,row in ipairs(BuffTap.options.blessingMenu.priorityRows) do assert(row.key~='bos') end")
test('Revoke never becomes a maintenance action',solo+"spell(1325499,'Revoke',26); BuffTap.bookDirty=true; refresh(); for _,b in ipairs(BuffTap.Buffs) do for _,id in ipairs(b.ranks) do assert(id~=1325499 and id~=1912) end end; assert(BuffTap.action.id==1038)")
print('ALL',len(tests),'SCENARIOS PASSED')
